-- ============================================================================
-- BEGIN 20260814000100_extensions_enums.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0100 — Extensions & Enumerated Types
-- ============================================================================
-- Establishes the vocabulary the rest of the schema is written in. Enums are
-- used instead of `text + CHECK` so that (a) the pipeline is enforced at the
-- type level and (b) Supabase's type generator emits a real TypeScript union
-- for the frontend rather than a bare `string`.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Extensions
-- ---------------------------------------------------------------------------

-- gen_random_uuid() is core since PG13, so nothing here depends on pgcrypto —
-- it is installed only so digest()/hmac() are available if webhook signature
-- verification is added later. Wrapped because the `extensions` schema is a
-- Supabase convention that a plain Postgres target will not have.
do $$
begin
  create extension if not exists pgcrypto with schema extensions;
exception
  when others then
    begin
      create extension if not exists pgcrypto;
    exception when others then
      raise notice 'pgcrypto unavailable (%); not required by this schema.', sqlerrm;
    end;
end $$;

-- pg_cron drives the Stale Lead Recycling Engine (migration 0800). It is
-- wrapped defensively: some managed/CI environments do not ship the extension,
-- and a hard failure here would block the entire schema from being created.
-- If it is unavailable the schema still applies cleanly and the recycler can be
-- driven externally via public.admin_run_recycle_now().
do $$
begin
  create extension if not exists pg_cron;
exception
  when others then
    raise notice
      'pg_cron unavailable (%). Schema will apply, but the stale-lead sweep '
      'must be triggered externally (see README).', sqlerrm;
end $$;

-- ---------------------------------------------------------------------------
-- Enumerated types
-- ---------------------------------------------------------------------------
-- Created idempotently so the file can be replayed against an existing database
-- without erroring (CREATE TYPE has no IF NOT EXISTS).

do $$ begin
  create type public.user_role as enum ('admin', 'telecaller');
exception when duplicate_object then null; end $$;

-- The standardised sales pipeline. Order of declaration is the natural forward
-- progression, which also gives us a free sort order for funnel reporting
-- (enums sort by declaration order, not alphabetically).
do $$ begin
  create type public.lead_status as enum (
    'new',
    'attempted',
    'connected',
    'warm',
    'rescheduled',
    'converted',
    'dead'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.lead_source as enum ('manual', 'csv', 'webhook');
exception when duplicate_object then null; end $$;

-- Every distinct thing that can appear on a lead's timeline.
do $$ begin
  create type public.audit_event as enum (
    'lead_created',
    'assigned',
    'reassigned',
    'unassigned',
    'status_changed',
    'remark_added',
    'reschedule_set',
    'sla_revoked',
    'lead_archived'
  );
exception when duplicate_object then null; end $$;

comment on type public.lead_status is
  'Standardised Fenlark pipeline. Movement is deliberately unrestricted (a lead '
  'may move backwards); the audit trail is what makes reversals accountable.';

comment on type public.audit_event is
  'Discriminator for lead_history_logs. sla_revoked is written only by the '
  'automated recycling engine.';

-- END 20260814000100_extensions_enums.sql


-- ============================================================================
-- BEGIN 20260814000200_tables.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0200 — Core Tables
-- ============================================================================
-- Four tables: users (auth profile), leads, lead_history_logs (append-only
-- audit trail) and system_settings (singleton config).
-- ============================================================================


-- ---------------------------------------------------------------------------
-- Phone normalisation
-- ---------------------------------------------------------------------------
-- Defined here (not in 0300) because public.leads depends on it for a STORED
-- generated column, so it must exist before the table.
--
-- A naive regexp_replace(phone, '[^0-9]', '', 'g') is NOT sufficient for the
-- duplicate-blocking requirement: the same person arrives as '9876543210' from
-- a CSV and '+91 98765 43210' from a Facebook/webhook lead, which strip to
-- '9876543210' and '919876543210' — two different keys, and two telecallers
-- calling the same person. This canonicalises to the bare national number.
--
-- MUST be IMMUTABLE to be legal in a generated column.
--
-- WARNING: because a stored generated column depends on this function, editing
-- it does NOT recompute existing rows. See README ("Changing phone
-- normalisation") for the required backfill procedure.
create or replace function public.normalize_phone(p_phone text)
returns text
language sql
immutable
parallel safe
as $$
  select case
    -- +91 98765 43210 / 919876543210  -> 9876543210
    when length(d) = 12 and left(d, 2) = '91' then right(d, 10)
    -- 098765 43210                    -> 9876543210
    when length(d) = 11 and left(d, 1) = '0'  then right(d, 10)
    else d
  end
  from (
    select regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') as d
  ) s;
$$;

comment on function public.normalize_phone(text) is
  'Canonicalises an Indian phone number to its bare 10-digit national form so '
  'that CSV, manual and webhook variants of the same number collide on the '
  'unique index. Mirrored by lib/phone.ts on the frontend — keep in sync.';


-- ---------------------------------------------------------------------------
-- users — profile mirror of auth.users
-- ---------------------------------------------------------------------------
-- Keyed to auth.users(id) rather than being a standalone table. Any other
-- design forks application identity from auth.uid() and breaks every RLS
-- policy in migration 0500.
create table if not exists public.users (
  id          uuid primary key references auth.users (id) on delete cascade,
  email       text not null unique,
  full_name   text not null check (length(btrim(full_name)) > 0),
  phone       text,
  role        public.user_role not null default 'telecaller',
  -- Drives "actively selected telecallers" in round-robin distribution.
  -- Deactivating a caller removes them from assignment without deleting the
  -- person, which would take their audit history with them.
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists users_role_active_idx
  on public.users (role, is_active);

comment on column public.users.is_active is
  'False removes the user from round-robin distribution and admin pickers '
  'without destroying their audit history. Prefer this over deletion.';


-- ---------------------------------------------------------------------------
-- leads
-- ---------------------------------------------------------------------------
create table if not exists public.leads (
  id                uuid primary key default gen_random_uuid(),

  full_name         text not null check (length(btrim(full_name)) > 0),
  phone             text not null,
  phone_normalized  text generated always as (public.normalize_phone(phone)) stored,
  email             text,
  city              text,
  company           text,
  notes             text,

  source            public.lead_source not null default 'manual',
  -- Raw inbound payload (CSV row / webhook body) retained verbatim for
  -- forensics: "where did this bad number come from?"
  source_meta       jsonb not null default '{}'::jsonb,

  status            public.lead_status not null default 'new',

  assigned_to       uuid references public.users (id) on delete set null,
  -- The SLA clock. Maintained exclusively by enforce_lead_update_rules() in
  -- migration 0300 — never written by a client, an RPC, or by hand. That is
  -- what makes the recycling engine impossible to game by backdating.
  assigned_at       timestamptz,

  last_contacted_at timestamptz,
  scheduled_at      timestamptz,          -- next follow-up
  last_remark       text,                 -- denormalised for fast list rendering
  sla_revoked_count integer not null default 0,

  created_by        uuid references public.users (id) on delete set null,
  -- Soft delete only. See migration 0400 for why hard deletes are impossible.
  deleted_at        timestamptz,

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  constraint leads_phone_plausible
    check (length(public.normalize_phone(phone)) between 7 and 15)
);

-- Hard-block duplicates. Partial on deleted_at so archiving a lead releases the
-- number for future campaigns rather than burning it permanently.
create unique index if not exists leads_phone_unique
  on public.leads (phone_normalized)
  where deleted_at is null;

-- Telecaller queue: "my leads, by pipeline stage".
create index if not exists leads_assigned_status_idx
  on public.leads (assigned_to, status)
  where deleted_at is null;

-- Admin unassigned pool + conversion funnel counts.
create index if not exists leads_status_idx
  on public.leads (status)
  where deleted_at is null;

-- "Due Soon" / "Overdue" follow-up surfacing.
create index if not exists leads_scheduled_idx
  on public.leads (scheduled_at)
  where scheduled_at is not null and deleted_at is null;

-- The SLA sweep (migration 0800). Narrowly partial so the recycler touches a
-- handful of rows instead of seq-scanning the whole lead table every 15 min.
create index if not exists leads_sla_sweep_idx
  on public.leads (assigned_at)
  where status = 'new' and assigned_to is not null and deleted_at is null;

comment on column public.leads.assigned_at is
  'Set automatically whenever assigned_to changes. Client-supplied values are '
  'overwritten by trigger — the SLA clock cannot be backdated.';


-- ---------------------------------------------------------------------------
-- lead_history_logs — append-only audit trail
-- ---------------------------------------------------------------------------
create table if not exists public.lead_history_logs (
  id            bigint generated always as identity primary key,

  -- Deliberately NOT "on delete cascade": a cascade would trip the
  -- immutability guard in 0400 and make lead deletion fail in a confusing way.
  -- Leads are soft-deleted instead.
  lead_id       uuid not null references public.leads (id),

  actor_id      uuid references public.users (id) on delete set null,
  -- Survives actor_id being nulled by a user deletion. A departed telecaller's
  -- row can disappear without erasing the fact that *something happened*.
  actor_kind    text not null default 'user'
                  check (actor_kind in ('user', 'system')),

  event_type    public.audit_event not null,

  from_status   public.lead_status,
  to_status     public.lead_status,
  from_assignee uuid references public.users (id) on delete set null,
  to_assignee   uuid references public.users (id) on delete set null,

  remark        text,
  scheduled_at  timestamptz,
  -- Free-text system annotation, e.g.
  -- 'System revoked assignment due to SLA breach.'
  note          text,

  created_at    timestamptz not null default now()
);

-- The lead timeline, newest first.
create index if not exists lead_history_lead_idx
  on public.lead_history_logs (lead_id, created_at desc);

-- Per-telecaller productivity ("Calls Made Today").
create index if not exists lead_history_actor_idx
  on public.lead_history_logs (actor_id, created_at desc);

create index if not exists lead_history_event_idx
  on public.lead_history_logs (event_type, created_at desc);

comment on table public.lead_history_logs is
  'Append-only. Enforced three independent ways: no UPDATE/DELETE policy '
  '(0500), revoked table grants (0500), and a raising trigger (0400).';


-- ---------------------------------------------------------------------------
-- system_settings — singleton
-- ---------------------------------------------------------------------------
-- The `id boolean primary key default true check (id)` idiom makes a second
-- row structurally impossible: the only value that satisfies the CHECK is
-- true, and the PK forbids a duplicate of it.
create table if not exists public.system_settings (
  id                      boolean primary key default true check (id),

  -- Stale Lead Recycling Engine
  stale_recycling_enabled boolean not null default true,
  stale_sla_hours         integer not null default 72
                            check (stale_sla_hours between 1 and 720),

  -- One-click WhatsApp. {{name}} and {{agent}} are substituted client-side.
  whatsapp_template       text not null default
    'Hello {{name}}, this is {{agent}} from Fenlark Technologies. '
    'Thank you for your interest in our digital marketing and web development '
    'services. When would be a good time to connect?',

  -- Keeps distribution fair across separate batches. Without it every batch
  -- restarts at telecaller #1, and the first name in the list quietly
  -- accumulates the heaviest workload over a week.
  round_robin_cursor      integer not null default 0 check (round_robin_cursor >= 0),

  -- "Calls Made Today" must reset at IST midnight, not UTC midnight — a UTC
  -- boundary would roll the counter over at 05:30 IST, mid-shift.
  report_timezone         text not null default 'Asia/Kolkata',

  updated_by              uuid references public.users (id) on delete set null,
  updated_at              timestamptz not null default now()
);

comment on table public.system_settings is
  'Single-row configuration. Read at runtime by the recycling engine, so SLA '
  'changes made in the admin UI take effect on the next tick with no redeploy.';

-- END 20260814000200_tables.sql


-- ============================================================================
-- BEGIN 20260814000300_helpers_guards.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0300 — Authorisation Helpers & Write Guards
-- ============================================================================
-- These functions are the load-bearing pieces of the security model. The RLS
-- policies in 0500 are thin wrappers around them.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- is_admin() — used by nearly every policy and RPC
-- ---------------------------------------------------------------------------
-- MUST be SECURITY DEFINER.
--
-- The RLS policy on public.users needs to know the caller's role, which means
-- reading public.users. If this lookup ran as the caller it would re-trigger
-- that same policy, which would call this function again, and Postgres errors
-- out with "infinite recursion detected in policy for relation users". Running
-- as the function owner bypasses RLS for this one lookup and breaks the cycle.
--
-- `set search_path = public` prevents a caller from shadowing `users` with a
-- temp table — a real privilege-escalation vector in SECURITY DEFINER code.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.users u
    where u.id = auth.uid()
      and u.role = 'admin'
      and u.is_active
  );
$$;

-- Ownership check for the audit-log read policy. Also SECURITY DEFINER so the
-- policy on lead_history_logs does not have to re-enter the policy on leads.
create or replace function public.owns_lead(p_lead_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.leads l
    where l.id = p_lead_id
      and l.assigned_to = auth.uid()
      and l.deleted_at is null
  );
$$;

-- True when the current statement originates from the automated recycler
-- rather than a human. Set transaction-locally by recycle_stale_leads().
create or replace function public.is_system_actor()
returns boolean
language sql
stable
as $$
  select coalesce(nullif(current_setting('app.actor_kind', true), ''), 'user') = 'system';
$$;

comment on function public.is_admin() is
  'SECURITY DEFINER by necessity — a SECURITY INVOKER version causes infinite '
  'recursion in the public.users RLS policy.';


-- ---------------------------------------------------------------------------
-- Auth provisioning
-- ---------------------------------------------------------------------------
-- Mirrors every new auth.users row into public.users so signup can never leave
-- an authenticated user with no profile (which would make is_admin() false and
-- every lead invisible, presenting as a mysterious empty dashboard).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.users (id, email, full_name, role)
  values (
    new.id,
    new.email,
    coalesce(
      nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(btrim(new.raw_user_meta_data ->> 'name'), ''),
      split_part(new.email, '@', 1)
    ),
    -- Role is never taken from user-supplied signup metadata; that would let
    -- anyone self-register as an admin. Promotion is an explicit admin action.
    'telecaller'
  )
  on conflict (id) do nothing;

  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();


-- ---------------------------------------------------------------------------
-- Generic updated_at maintenance
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists trg_users_touch on public.users;
create trigger trg_users_touch
  before update on public.users
  for each row execute function public.touch_updated_at();

drop trigger if exists trg_settings_touch on public.system_settings;
create trigger trg_settings_touch
  before update on public.system_settings
  for each row execute function public.touch_updated_at();


-- ---------------------------------------------------------------------------
-- enforce_lead_update_rules() — field-level restriction
-- ---------------------------------------------------------------------------
-- RLS decides *which rows* you may touch. This decides *which columns*.
--
-- Why a trigger rather than column grants: GRANT UPDATE (col) ON leads TO
-- authenticated is the textbook answer, but admins and telecallers are both
-- the `authenticated` Postgres role. Column privileges are role-wide, so
-- locking telecallers out of `phone` would lock admins out too. A trigger can
-- branch on is_admin() at runtime; a GRANT cannot.
create or replace function public.enforce_lead_update_rules()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_is_admin  boolean;
  v_is_system boolean := public.is_system_actor();
begin
  -- Keep updated_at honest regardless of who is writing.
  new.updated_at := now();

  -- The SLA clock is owned by this trigger alone. Whatever the caller supplied
  -- for assigned_at is discarded and recomputed from the assignment change,
  -- so no client, RPC or manual UPDATE can backdate it to dodge recycling.
  if new.assigned_to is distinct from old.assigned_to then
    new.assigned_at := case when new.assigned_to is null then null else now() end;
  else
    new.assigned_at := old.assigned_at;
  end if;

  -- The recycling engine runs under pg_cron with no JWT, so auth.uid() is null
  -- and is_admin() is false. Without this branch the engine's own UPDATE would
  -- be rejected by the assignment lock below.
  if v_is_system then
    return new;
  end if;

  v_is_admin := public.is_admin();

  if not v_is_admin then
    -- Identity and provenance are admin-owned. A telecaller correcting a wrong
    -- number would silently break the dedupe key and the audit chain.
    if new.phone is distinct from old.phone
       or new.full_name is distinct from old.full_name
       or new.email is distinct from old.email
       or new.source is distinct from old.source
       or new.source_meta is distinct from old.source_meta
       or new.created_by is distinct from old.created_by
       or new.sla_revoked_count is distinct from old.sla_revoked_count
       or new.deleted_at is distinct from old.deleted_at
    then
      raise exception
        'Telecallers may not modify lead identity, provenance or archival fields'
        using errcode = '42501';
    end if;

    -- A telecaller may never move a lead — not to someone else, and not to
    -- themselves. This is the second lock on assignment; the WITH CHECK clause
    -- in 0500 is the first.
    if new.assigned_to is distinct from old.assigned_to then
      raise exception
        'Telecallers may not reassign leads. Ask an admin to transfer this lead.'
        using errcode = '42501';
    end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_leads_enforce_update on public.leads;
create trigger trg_leads_enforce_update
  before update on public.leads
  for each row execute function public.enforce_lead_update_rules();


-- Keep assigned_at consistent on INSERT too (admin creating a pre-assigned lead).
--
-- Unlike UPDATE, INSERT honours an explicitly supplied assigned_at. That is
-- what makes migrating an existing spreadsheet with historical assignment
-- dates possible. It is not a hole in the SLA guarantee: a backdated insert
-- only makes the lead *more* eligible for recycling, and INSERT is admin-only.
-- Once the row exists the clock is sealed — no UPDATE can move it.
create or replace function public.enforce_lead_insert_rules()
returns trigger
language plpgsql
as $$
begin
  new.assigned_at := case
    when new.assigned_to is null then null
    else coalesce(new.assigned_at, now())
  end;
  return new;
end $$;

drop trigger if exists trg_leads_enforce_insert on public.leads;
create trigger trg_leads_enforce_insert
  before insert on public.leads
  for each row execute function public.enforce_lead_insert_rules();


-- ---------------------------------------------------------------------------
-- enforce_user_update_rules() — privilege-escalation lock
-- ---------------------------------------------------------------------------
-- The users UPDATE policy in 0500 lets a user edit their own row so they can
-- fix their name or phone. Without this guard that same policy would let a
-- telecaller run `update users set role = 'admin' where id = auth.uid()`.
create or replace function public.enforce_user_update_rules()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_system_actor() or public.is_admin() then
    return new;
  end if;

  if new.role is distinct from old.role
     or new.is_active is distinct from old.is_active
     or new.email is distinct from old.email
     or new.id is distinct from old.id
  then
    raise exception 'Only an admin may change role, activation status or email'
      using errcode = '42501';
  end if;

  return new;
end $$;

drop trigger if exists trg_users_enforce_update on public.users;
create trigger trg_users_enforce_update
  before update on public.users
  for each row execute function public.enforce_user_update_rules();

-- END 20260814000300_helpers_guards.sql


-- ============================================================================
-- BEGIN 20260814000400_audit_triggers.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0400 — Immutable Audit Trail
-- ============================================================================
-- Two guarantees, enforced structurally rather than by convention:
--
--   1. Every meaningful change to a lead writes a log row. There is no write
--      path to public.leads that skips this trigger.
--   2. No log row can ever be altered or removed.
--
-- Together these mean the timeline is a faithful record even when a status is
-- reversed months later.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- Immutability
-- ---------------------------------------------------------------------------
-- Applies to everyone, including the table owner and superusers. That is the
-- point: "immutable" that an admin can quietly edit is not immutable.
create or replace function public.prevent_log_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception
    'lead_history_logs is append-only; % is not permitted on the audit trail', tg_op
    using errcode = '42501',
          hint = 'Corrections are made by adding a new log entry, never by editing one.';
end $$;

drop trigger if exists trg_logs_no_update on public.lead_history_logs;
create trigger trg_logs_no_update
  before update on public.lead_history_logs
  for each row execute function public.prevent_log_mutation();

drop trigger if exists trg_logs_no_delete on public.lead_history_logs;
create trigger trg_logs_no_delete
  before delete on public.lead_history_logs
  for each row execute function public.prevent_log_mutation();

-- A row trigger cannot see TRUNCATE, so block it separately — otherwise the
-- entire trail could be erased in one statement.
create or replace function public.prevent_log_truncate()
returns trigger
language plpgsql
as $$
begin
  raise exception 'lead_history_logs is append-only; TRUNCATE is not permitted'
    using errcode = '42501';
end $$;

drop trigger if exists trg_logs_no_truncate on public.lead_history_logs;
create trigger trg_logs_no_truncate
  before truncate on public.lead_history_logs
  for each statement execute function public.prevent_log_truncate();


-- ---------------------------------------------------------------------------
-- log_lead_change() — the single audit writer
-- ---------------------------------------------------------------------------
-- SECURITY DEFINER, so it writes as the table owner and bypasses RLS. That is
-- why lead_history_logs needs no INSERT policy for `authenticated` at all:
-- clients cannot forge log rows, and the only way a row appears is that a real
-- change occurred.
--
-- Actor resolution: auth.uid() when a JWT is present. The recycling engine runs
-- under pg_cron with no JWT, so it announces itself via two transaction-local
-- GUCs (app.actor_kind, app.audit_note) which this function reads below.
create or replace function public.log_lead_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_kind  text := coalesce(nullif(current_setting('app.actor_kind', true), ''), 'user');
  v_note  text := nullif(current_setting('app.audit_note', true), '');
begin
  -- A system action is attributed to the system, never to whoever happened to
  -- be logged in. admin_run_recycle_now() runs under an admin's JWT, so without
  -- this the same SLA revocation would read "Aditi revoked this lead" when
  -- triggered from the settings panel and "system" when triggered by cron —
  -- for a decision neither of them made. The SLA did.
  if v_kind = 'system' then
    v_actor := null;
  end if;

  if tg_op = 'INSERT' then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, to_status, to_assignee, note
    )
    values (new.id, v_actor, v_kind, 'lead_created', new.status, new.assigned_to, v_note);

    -- A lead created already-assigned produces two entries, so the assignment
    -- has its own timestamped record rather than being implied by creation.
    if new.assigned_to is not null then
      insert into public.lead_history_logs (
        lead_id, actor_id, actor_kind, event_type, to_assignee
      )
      values (new.id, v_actor, v_kind, 'assigned', new.assigned_to);
    end if;

    return null;
  end if;

  -- ---- UPDATE ----

  if new.assigned_to is distinct from old.assigned_to then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, from_assignee, to_assignee, note
    )
    values (
      new.id, v_actor, v_kind,
      case
        when old.assigned_to is null                     then 'assigned'
        when new.assigned_to is null and v_kind = 'system' then 'sla_revoked'
        when new.assigned_to is null                     then 'unassigned'
        else 'reassigned'
      end::public.audit_event,
      old.assigned_to, new.assigned_to, v_note
    );
  end if;

  if new.status is distinct from old.status then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, from_status, to_status, note
    )
    values (new.id, v_actor, v_kind, 'status_changed', old.status, new.status, v_note);
  end if;

  -- Only forward-looking reschedules are logged; clearing the date on a
  -- converted/dead lead is bookkeeping, not a follow-up commitment.
  if new.scheduled_at is distinct from old.scheduled_at
     and new.scheduled_at is not null then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, scheduled_at
    )
    values (new.id, v_actor, v_kind, 'reschedule_set', new.scheduled_at);
  end if;

  if new.deleted_at is not null and old.deleted_at is null then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, note
    )
    values (new.id, v_actor, v_kind, 'lead_archived', v_note);
  end if;

  -- NOTE: changes to last_remark are deliberately not logged here.
  -- public.log_call_interaction() writes the authoritative 'remark_added'
  -- entry with its own before/after status; logging it here as well would
  -- double every remark on the timeline.

  return null;
end $$;

drop trigger if exists trg_leads_audit on public.leads;
create trigger trg_leads_audit
  after insert or update on public.leads
  for each row execute function public.log_lead_change();

comment on function public.log_lead_change() is
  'Sole writer of the audit trail. SECURITY DEFINER so it bypasses RLS — '
  'clients therefore need (and have) no INSERT privilege on lead_history_logs.';

-- END 20260814000400_audit_triggers.sql


-- ============================================================================
-- BEGIN 20260814000500_rls_policies.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0500 — Row Level Security
-- ============================================================================
-- Data isolation lives here, in Postgres — not in React. A leaked anon key, a
-- hand-rolled fetch() against the REST endpoint, or a bug in a server component
-- still cannot walk the lead table.
--
-- Deliberate omission: ENABLE, not FORCE.
-- FORCE ROW LEVEL SECURITY would subject the table *owner* to RLS as well, and
-- the audit trigger in 0400 runs SECURITY DEFINER as that owner. Under FORCE it
-- would need an INSERT policy on lead_history_logs — and any policy permissive
-- enough for the trigger would also be usable by clients to forge log entries.
-- Plain ENABLE keeps the trigger working while clients stay fully governed.
-- ============================================================================

alter table public.users              enable row level security;
alter table public.leads              enable row level security;
alter table public.lead_history_logs  enable row level security;
alter table public.system_settings    enable row level security;


-- ---------------------------------------------------------------------------
-- Table grants
-- ---------------------------------------------------------------------------
-- RLS filters rows, but only among the operations a role is granted at all.
-- Removing DELETE at the grant level means no policy mistake can ever expose
-- deletion to a client.

revoke all on public.users             from anon, authenticated;
revoke all on public.leads             from anon, authenticated;
revoke all on public.lead_history_logs from anon, authenticated;
revoke all on public.system_settings   from anon, authenticated;

grant select, insert, update on public.users            to authenticated;
grant select, insert, update on public.leads            to authenticated;
grant select                 on public.lead_history_logs to authenticated;
grant select, update         on public.system_settings  to authenticated;

-- anon (pre-login) gets nothing at all.


-- ---------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------
drop policy if exists users_select on public.users;
create policy users_select on public.users
  for select to authenticated
  using (id = auth.uid() or public.is_admin());

drop policy if exists users_insert_admin on public.users;
create policy users_insert_admin on public.users
  for insert to authenticated
  with check (public.is_admin());

-- Self-service profile edits are allowed; the guard trigger in 0300 freezes
-- role, is_active and email so this cannot become a privilege escalation.
drop policy if exists users_update on public.users;
create policy users_update on public.users
  for update to authenticated
  using      (id = auth.uid() or public.is_admin())
  with check (id = auth.uid() or public.is_admin());

-- No DELETE policy. Deactivate via is_active instead — deleting a user would
-- null out their actor_id across the audit trail.


-- ---------------------------------------------------------------------------
-- leads — the core isolation guarantee
-- ---------------------------------------------------------------------------
drop policy if exists leads_select on public.leads;
create policy leads_select on public.leads
  for select to authenticated
  using (
    public.is_admin()
    or (assigned_to = auth.uid() and deleted_at is null)
  );

drop policy if exists leads_insert_admin on public.leads;
create policy leads_insert_admin on public.leads
  for insert to authenticated
  with check (public.is_admin());

-- USING gates which rows may be targeted; WITH CHECK gates the row's state
-- *after* the write. Both are required.
--
-- With USING alone, a telecaller could run
--     update leads set assigned_to = '<another caller>' where id = '<mine>';
-- The pre-image passes (they own it), the row is written, and the lead is gone
-- from their queue — an unlogged transfer they had no right to make. WITH CHECK
-- rejects the post-image. The guard trigger in 0300 rejects it a second time.
drop policy if exists leads_update on public.leads;
create policy leads_update on public.leads
  for update to authenticated
  using      (public.is_admin() or (assigned_to = auth.uid() and deleted_at is null))
  with check (public.is_admin() or (assigned_to = auth.uid() and deleted_at is null));

-- No DELETE policy, and DELETE is not granted. Archival is admin_archive_lead().


-- ---------------------------------------------------------------------------
-- lead_history_logs
-- ---------------------------------------------------------------------------
-- SELECT only. There is no INSERT policy by design (see the header note): the
-- audit trigger writes as owner and bypasses RLS entirely.
drop policy if exists logs_select on public.lead_history_logs;
create policy logs_select on public.lead_history_logs
  for select to authenticated
  using (public.is_admin() or public.owns_lead(lead_id));


-- ---------------------------------------------------------------------------
-- system_settings
-- ---------------------------------------------------------------------------
-- Readable by everyone: telecallers need whatsapp_template and report_timezone.
drop policy if exists settings_select on public.system_settings;
create policy settings_select on public.system_settings
  for select to authenticated
  using (true);

drop policy if exists settings_update_admin on public.system_settings;
create policy settings_update_admin on public.system_settings
  for update to authenticated
  using      (public.is_admin())
  with check (public.is_admin());


-- ---------------------------------------------------------------------------
-- telecaller_directory
-- ---------------------------------------------------------------------------
-- Telecallers must render actor names on a lead's audit timeline, but the
-- users policy above deliberately hides other users' rows (which carry email
-- and phone). Postgres has no column-level RLS, so a view owned by the schema
-- owner provides column-level exposure instead: id, name and status only.
create or replace view public.telecaller_directory
with (security_invoker = false) as
  select u.id, u.full_name, u.role, u.is_active
  from public.users u;

revoke all on public.telecaller_directory from anon, authenticated;
grant select on public.telecaller_directory to authenticated;

comment on view public.telecaller_directory is
  'Name-only projection of public.users. security_invoker = false so it runs '
  'with the view owner''s rights, exposing names without exposing contact '
  'details. Join audit-timeline actor_id against this, not against users.';


-- ---------------------------------------------------------------------------
-- Function execution grants
-- ---------------------------------------------------------------------------
-- Revoke from PUBLIC, not from anon: EXECUTE is granted to PUBLIC by default,
-- and revoking from anon alone leaves that blanket grant in place.
revoke execute on function public.is_admin()                      from public;
revoke execute on function public.owns_lead(uuid)                 from public;
revoke execute on function public.normalize_phone(text)           from public;

grant execute on function public.is_admin()                       to authenticated;
grant execute on function public.owns_lead(uuid)                  to authenticated;
grant execute on function public.normalize_phone(text)            to authenticated;

-- END 20260814000500_rls_policies.sql


-- ============================================================================
-- BEGIN 20260814000600_rpc_admin.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0600 — Admin RPCs
-- ============================================================================
-- Admin mutations go through these functions rather than direct table writes,
-- which keeps validation, authorisation and audit in one place.
--
-- Every function here is SECURITY DEFINER and therefore bypasses RLS — so
-- every one of them re-checks is_admin() as its first statement. A SECURITY
-- DEFINER function that skips its own authorisation check is an open door
-- straight past every policy in 0500.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- admin_import_leads — CSV / manual / webhook ingestion
-- ---------------------------------------------------------------------------
-- Duplicates are hard-blocked. Returns a breakdown so the upload modal can
-- report "312 imported · 14 duplicates · 3 invalid" instead of failing opaquely
-- on the first bad row.
create or replace function public.admin_import_leads(
  p_rows   jsonb,
  p_source public.lead_source default 'csv'
)
returns table (inserted integer, skipped_duplicate integer, skipped_invalid integer)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_total integer;
  v_valid integer;
  v_ins   integer;
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'p_rows must be a JSON array of lead objects';
  end if;

  with src as (
    select
      nullif(btrim(t.r ->> 'full_name'), '') as full_name,
      nullif(btrim(t.r ->> 'phone'), '')     as phone,
      nullif(btrim(t.r ->> 'email'), '')     as email,
      nullif(btrim(t.r ->> 'city'), '')      as city,
      nullif(btrim(t.r ->> 'company'), '')   as company,
      nullif(btrim(t.r ->> 'notes'), '')     as notes,
      t.r                                    as raw
    from jsonb_array_elements(p_rows) as t(r)
  ),
  valid as (
    select * from src
    where full_name is not null
      and phone is not null
      and length(public.normalize_phone(phone)) between 7 and 15
  ),
  -- Collapse duplicates *within* the batch first. ON CONFLICT resolves each
  -- row against rows already committed; two identical numbers in the same
  -- upload need handling here.
  deduped as (
    select distinct on (public.normalize_phone(phone)) *
    from valid
    order by public.normalize_phone(phone)
  ),
  ins as (
    insert into public.leads (
      full_name, phone, email, city, company, notes, source, source_meta, created_by
    )
    select full_name, phone, email, city, company, notes, p_source, raw, v_actor
    from deduped
    -- Bare DO NOTHING, so it works against the partial unique index
    -- leads_phone_unique without restating its predicate.
    on conflict do nothing
    returning 1
  )
  select
    (select count(*) from src)::integer,
    (select count(*) from valid)::integer,
    (select count(*) from ins)::integer
  into v_total, v_valid, v_ins;

  return query select v_ins, (v_valid - v_ins), (v_total - v_valid);
end $$;


-- ---------------------------------------------------------------------------
-- admin_assign_leads — manual assignment / return to pool
-- ---------------------------------------------------------------------------
-- Pass p_user_id => null to strip assignment and return leads to the
-- unassigned pool manually (the same effect the SLA engine produces, but
-- logged as 'unassigned' by a named admin rather than 'sla_revoked').
create or replace function public.admin_assign_leads(
  p_lead_ids uuid[],
  p_user_id  uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  if p_lead_ids is null or array_length(p_lead_ids, 1) is null then
    raise exception 'no leads selected';
  end if;

  if p_user_id is not null and not exists (
    select 1 from public.users
    where id = p_user_id and role = 'telecaller' and is_active
  ) then
    raise exception 'target must be an active telecaller'
      using hint = 'Deactivated users cannot receive new leads.';
  end if;

  update public.leads
     set assigned_to = p_user_id
   where id = any(p_lead_ids)
     and deleted_at is null
     and assigned_to is distinct from p_user_id;

  get diagnostics v_count = row_count;
  return v_count;
end $$;


-- ---------------------------------------------------------------------------
-- admin_round_robin_assign — even batch distribution
-- ---------------------------------------------------------------------------
-- Deterministic modulo distribution, resumed from and advanced past
-- system_settings.round_robin_cursor so consecutive batches keep the workload
-- level rather than always reloading the alphabetically-first telecaller.
create or replace function public.admin_round_robin_assign(
  p_lead_ids uuid[],
  p_user_ids uuid[]
)
returns table (user_id uuid, full_name text, assigned_count integer)
language plpgsql
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_n      integer;
  v_cursor integer;
  v_leads  integer;
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  if p_lead_ids is null or array_length(p_lead_ids, 1) is null then
    raise exception 'no leads selected';
  end if;

  select count(*) into v_n
  from public.users u
  where u.id = any(p_user_ids) and u.role = 'telecaller' and u.is_active;

  -- Guard the modulo below: v_n = 0 would be a division-by-zero rather than a
  -- comprehensible error.
  if v_n = 0 then
    raise exception 'no active telecallers in the selection'
      using hint = 'Deactivated users are excluded from round-robin distribution.';
  end if;

  select count(*) into v_leads
  from public.leads l
  where l.id = any(p_lead_ids) and l.deleted_at is null;

  if v_leads = 0 then
    raise exception 'none of the selected leads are available for assignment';
  end if;

  select s.round_robin_cursor into v_cursor
  from public.system_settings s where s.id = true;
  v_cursor := coalesce(v_cursor, 0);

  with targets as (
    select u.id, (row_number() over (order by u.full_name, u.id) - 1)::integer as idx
    from public.users u
    where u.id = any(p_user_ids) and u.role = 'telecaller' and u.is_active
  ),
  ordered as (
    select l.id, (row_number() over (order by l.created_at, l.id) - 1)::integer as rn
    from public.leads l
    where l.id = any(p_lead_ids) and l.deleted_at is null
  )
  update public.leads l
     set assigned_to = t.id
    from ordered o
    join targets t on t.idx = ((o.rn + v_cursor) % v_n)
   where l.id = o.id
     and l.assigned_to is distinct from t.id;

  -- Advance the cursor by the number of leads distributed, so the next batch
  -- starts on the next telecaller in rotation.
  update public.system_settings
     set round_robin_cursor = (v_cursor + v_leads) % v_n,
         updated_by = auth.uid()
   where id = true;

  return query
    select u.id, u.full_name, count(l.id)::integer
    from public.users u
    left join public.leads l
      on l.assigned_to = u.id
     and l.id = any(p_lead_ids)
     and l.deleted_at is null
    where u.id = any(p_user_ids) and u.role = 'telecaller' and u.is_active
    group by u.id, u.full_name
    order by u.full_name;
end $$;

comment on function public.admin_round_robin_assign(uuid[], uuid[]) is
  'Even distribution across selected active telecallers. assigned_at and the '
  'assigned/reassigned audit entries are produced by the triggers in 0300/0400.';


-- ---------------------------------------------------------------------------
-- admin_archive_lead — soft delete
-- ---------------------------------------------------------------------------
create or replace function public.admin_archive_lead(
  p_lead_id uuid,
  p_reason  text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  perform set_config(
    'app.audit_note',
    coalesce(nullif(btrim(p_reason), ''), 'Archived by admin.'),
    true
  );

  update public.leads
     set deleted_at = now()
   where id = p_lead_id
     and deleted_at is null;

  if not found then
    raise exception 'lead not found or already archived' using errcode = 'P0002';
  end if;

  -- Assignment is intentionally left intact: the archived record should still
  -- show who was working it. The RLS predicate already hides archived leads
  -- from the telecaller's queue.
end $$;


-- ---------------------------------------------------------------------------
-- admin_update_settings
-- ---------------------------------------------------------------------------
-- Backs the Settings panel: the recycling ON/OFF toggle and the SLA hours
-- input. Null arguments leave the existing value untouched.
create or replace function public.admin_update_settings(
  p_enabled           boolean default null,
  p_sla_hours         integer default null,
  p_whatsapp_template text    default null
)
returns public.system_settings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row public.system_settings;
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  if p_sla_hours is not null and p_sla_hours not between 1 and 720 then
    raise exception 'SLA hours must be between 1 and 720 (30 days)';
  end if;

  update public.system_settings
     set stale_recycling_enabled = coalesce(p_enabled, stale_recycling_enabled),
         stale_sla_hours         = coalesce(p_sla_hours, stale_sla_hours),
         whatsapp_template       = coalesce(
                                     nullif(btrim(p_whatsapp_template), ''),
                                     whatsapp_template
                                   ),
         updated_by              = auth.uid()
   where id = true
  returning * into v_row;

  return v_row;
end $$;


-- ---------------------------------------------------------------------------
-- admin_set_user_role / admin_set_user_active
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_user_role(
  p_user_id uuid,
  p_role    public.user_role
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  update public.users set role = p_role where id = p_user_id;

  if not found then
    raise exception 'user not found' using errcode = 'P0002';
  end if;
end $$;

create or replace function public.admin_set_user_active(
  p_user_id uuid,
  p_active  boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  -- Refuse to strand the last admin: with no active admin, is_admin() is false
  -- for everyone and the settings panel becomes permanently unreachable.
  if p_active is false and exists (
    select 1 from public.users where id = p_user_id and role = 'admin'
  ) and (
    select count(*) from public.users where role = 'admin' and is_active
  ) <= 1 then
    raise exception 'cannot deactivate the last active admin';
  end if;

  update public.users set is_active = p_active where id = p_user_id;

  if not found then
    raise exception 'user not found' using errcode = 'P0002';
  end if;
end $$;


-- ---------------------------------------------------------------------------
-- Execution grants
-- ---------------------------------------------------------------------------
-- Postgres grants EXECUTE to PUBLIC by default; revoke before granting so
-- anon can never reach an admin RPC even though each re-checks is_admin().
revoke execute on function public.admin_import_leads(jsonb, public.lead_source)      from public;
revoke execute on function public.admin_assign_leads(uuid[], uuid)                   from public;
revoke execute on function public.admin_round_robin_assign(uuid[], uuid[])           from public;
revoke execute on function public.admin_archive_lead(uuid, text)                     from public;
revoke execute on function public.admin_update_settings(boolean, integer, text)      from public;
revoke execute on function public.admin_set_user_role(uuid, public.user_role)        from public;
revoke execute on function public.admin_set_user_active(uuid, boolean)               from public;

grant execute on function public.admin_import_leads(jsonb, public.lead_source)       to authenticated;
grant execute on function public.admin_assign_leads(uuid[], uuid)                    to authenticated;
grant execute on function public.admin_round_robin_assign(uuid[], uuid[])            to authenticated;
grant execute on function public.admin_archive_lead(uuid, text)                      to authenticated;
grant execute on function public.admin_update_settings(boolean, integer, text)       to authenticated;
grant execute on function public.admin_set_user_role(uuid, public.user_role)         to authenticated;
grant execute on function public.admin_set_user_active(uuid, boolean)                to authenticated;

-- END 20260814000600_rpc_admin.sql


-- ============================================================================
-- BEGIN 20260814000700_rpc_caller.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0700 — Telecaller RPCs & Queue View
-- ============================================================================


-- ---------------------------------------------------------------------------
-- log_call_interaction — the single write path for the disposition drawer
-- ---------------------------------------------------------------------------
-- Status change, remark and reschedule are one atomic operation, which is what
-- guarantees a remark can never be orphaned from the status it explains.
--
-- SECURITY DEFINER (it writes the audit row directly), and therefore it
-- re-verifies ownership itself. RLS does not protect the body of a SECURITY
-- DEFINER function — this check is the only thing standing in for it.
create or replace function public.log_call_interaction(
  p_lead_id      uuid,
  p_status       public.lead_status,
  p_remark       text,
  p_scheduled_at timestamptz default null
)
returns public.leads
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor      uuid := auth.uid();
  v_lead       public.leads;
  v_old_status public.lead_status;
  v_remark     text := nullif(btrim(p_remark), '');
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- FOR UPDATE: two devices logging the same lead simultaneously serialise
  -- here rather than racing and losing one of the two remarks.
  select * into v_lead
  from public.leads
  where id = p_lead_id and deleted_at is null
  for update;

  if not found then
    raise exception 'lead not found' using errcode = 'P0002';
  end if;

  if not (public.is_admin() or v_lead.assigned_to = v_actor) then
    raise exception 'forbidden: this lead is not assigned to you'
      using errcode = '42501';
  end if;

  if v_remark is null then
    raise exception 'a remark is required when logging a call';
  end if;

  -- A "Rescheduled" lead with no future date is the main way follow-ups get
  -- silently lost, so it is rejected at the database rather than trusted to
  -- client-side form validation.
  if p_status = 'rescheduled'
     and (p_scheduled_at is null or p_scheduled_at <= now()) then
    raise exception 'Rescheduled leads require a follow-up date/time in the future';
  end if;

  v_old_status := v_lead.status;

  update public.leads
     set status            = p_status,
         last_remark       = v_remark,
         last_contacted_at = now(),
         scheduled_at      = case
                               -- Closing a lead clears any pending follow-up.
                               when p_status in ('converted', 'dead') then null
                               else coalesce(p_scheduled_at, scheduled_at)
                             end
   where id = p_lead_id
  returning * into v_lead;

  -- The status_changed / reschedule_set entries come from the trigger in 0400.
  -- This adds the remark itself, carrying the status transition it explains so
  -- the timeline reads as one coherent event.
  insert into public.lead_history_logs (
    lead_id, actor_id, actor_kind, event_type, from_status, to_status, remark, scheduled_at
  )
  values (
    p_lead_id, v_actor, 'user', 'remark_added',
    v_old_status, p_status, v_remark, v_lead.scheduled_at
  );

  return v_lead;
end $$;

comment on function public.log_call_interaction(uuid, public.lead_status, text, timestamptz) is
  'Sole telecaller write path. Clients should never UPDATE public.leads '
  'directly — doing so bypasses the remark requirement and the reschedule '
  'validation, though not the audit trail.';


-- ---------------------------------------------------------------------------
-- my_dashboard_stats
-- ---------------------------------------------------------------------------
-- One round trip for the telecaller's personal dashboard.
--
-- "Today" is evaluated in system_settings.report_timezone, not UTC. On a UTC
-- boundary the Calls Made Today counter would reset at 05:30 IST — mid-shift,
-- with half the morning's calls already logged.
create or replace function public.my_dashboard_stats()
returns table (
  calls_made_today   integer,
  followups_pending  integer,
  followups_overdue  integer,
  assigned_total     integer,
  untouched_new      integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_tz    text;
  v_start timestamptz;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select report_timezone into v_tz from public.system_settings where id = true;
  v_tz := coalesce(v_tz, 'Asia/Kolkata');

  -- Computed as a constant so the comparison stays sargable against
  -- lead_history_actor_idx.
  v_start := date_trunc('day', now() at time zone v_tz) at time zone v_tz;

  return query
  select
    (select count(*) from public.lead_history_logs h
      where h.actor_id = v_actor
        and h.event_type = 'remark_added'
        and h.created_at >= v_start)::integer,

    (select count(*) from public.leads l
      where l.assigned_to = v_actor
        and l.deleted_at is null
        and l.scheduled_at is not null
        and l.scheduled_at >= now()
        and l.status not in ('converted', 'dead'))::integer,

    (select count(*) from public.leads l
      where l.assigned_to = v_actor
        and l.deleted_at is null
        and l.scheduled_at is not null
        and l.scheduled_at < now()
        and l.status not in ('converted', 'dead'))::integer,

    (select count(*) from public.leads l
      where l.assigned_to = v_actor
        and l.deleted_at is null)::integer,

    -- Surfaced deliberately: these are the leads the recycling engine will
    -- reclaim if the caller does not touch them before the SLA expires.
    (select count(*) from public.leads l
      where l.assigned_to = v_actor
        and l.deleted_at is null
        and l.status = 'new')::integer;
end $$;


-- ---------------------------------------------------------------------------
-- lead_queue — priority-ordered working view
-- ---------------------------------------------------------------------------
-- security_invoker = true, so the leads RLS policy applies with the *querying*
-- user's rights. A telecaller selecting from this view sees only their own
-- leads; an admin sees everything. One view, no duplicated filtering.
create or replace view public.lead_queue
with (security_invoker = true) as
select
  l.*,
  case
    when l.status in ('converted', 'dead')            then 'closed'
    when l.scheduled_at is null                       then 'unscheduled'
    when l.scheduled_at <  now()                      then 'overdue'
    when l.scheduled_at <  now() + interval '2 hours' then 'due_soon'
    when l.scheduled_at <  now() + interval '24 hours' then 'due_today'
    else 'scheduled'
  end as follow_up_bucket,
  -- Sort key for the caller's queue: overdue first, then imminent, then
  -- untouched new leads (which are burning SLA), then everything else.
  case
    when l.status in ('converted', 'dead')            then 90
    when l.scheduled_at <  now()                      then 10
    when l.scheduled_at <  now() + interval '2 hours' then 20
    when l.scheduled_at <  now() + interval '24 hours' then 30
    when l.status = 'new'                             then 40
    when l.scheduled_at is not null                   then 50
    else 60
  end as queue_rank,
  -- Hours remaining before the recycling engine reclaims this lead. Null when
  -- not applicable. Lets the UI warn "returns to pool in 4h".
  case
    when l.status = 'new' and l.assigned_at is not null then
      greatest(
        0,
        (select s.stale_sla_hours from public.system_settings s where s.id = true)
        - (extract(epoch from (now() - l.assigned_at)) / 3600)
      )
    else null
  end as sla_hours_remaining
from public.leads l
where l.deleted_at is null;

revoke all on public.lead_queue from anon, authenticated;
grant select on public.lead_queue to authenticated;

comment on view public.lead_queue is
  'Order by queue_rank, scheduled_at nulls last. Overdue and Due Soon rise to '
  'the top of the telecaller queue automatically.';


-- ---------------------------------------------------------------------------
-- Execution grants
-- ---------------------------------------------------------------------------
revoke execute on function public.log_call_interaction(uuid, public.lead_status, text, timestamptz) from public;
revoke execute on function public.my_dashboard_stats()                                              from public;

grant execute on function public.log_call_interaction(uuid, public.lead_status, text, timestamptz)  to authenticated;
grant execute on function public.my_dashboard_stats()                                               to authenticated;

-- END 20260814000700_rpc_caller.sql


-- ============================================================================
-- BEGIN 20260814000800_recycling_engine.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0800 — Stale Lead Recycling Engine
-- ============================================================================
-- If a lead sits at status 'new' in a telecaller's queue for longer than the
-- configured SLA, the assignment is stripped and the lead returns to the
-- admin's unassigned pool with an audit entry naming the system as the actor.
--
-- Implemented in Postgres rather than as an Edge Function so it keeps running
-- when the app is undeployed, mid-rollback, or simply down. The lead pool does
-- not depend on Vercel being healthy.
-- ============================================================================

create or replace function public.recycle_stale_leads()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_enabled boolean;
  v_hours   integer;
  v_count   integer;
begin
  -- Settings are read at runtime, never baked into the cron schedule: changing
  -- the SLA in the admin panel takes effect on the next tick with no migration
  -- and no redeploy.
  select stale_recycling_enabled, stale_sla_hours
    into v_enabled, v_hours
  from public.system_settings
  where id = true;

  if not coalesce(v_enabled, false) then
    return 0;
  end if;

  -- Announce the actor to the triggers. Transaction-local (the third argument
  -- to set_config), so the flag cannot leak into an unrelated session and let
  -- a human action be recorded as a system one.
  --
  -- These two GUCs are what turn the plain UPDATE below into a fully audited
  -- 'sla_revoked' entry: enforce_lead_update_rules() consults app.actor_kind to
  -- permit the assignment change, and log_lead_change() consults both to write
  -- the entry with the required wording.
  perform set_config('app.actor_kind', 'system', true);
  perform set_config(
    'app.audit_note',
    'System revoked assignment due to SLA breach.',
    true
  );

  with stale as (
    select id
    from public.leads
    where status = 'new'                -- a lead someone actually worked is never reclaimed
      and assigned_to is not null
      and assigned_at is not null
      -- make_interval() rather than string-concatenating an interval literal:
      -- stale_sla_hours ultimately originates in a UI input field.
      and assigned_at < now() - make_interval(hours => v_hours)
      and deleted_at is null
    -- SKIP LOCKED so a manual admin_run_recycle_now() overlapping the scheduled
    -- tick processes disjoint rows instead of blocking or deadlocking.
    for update skip locked
  )
  update public.leads l
     set assigned_to       = null,
         sla_revoked_count = l.sla_revoked_count + 1
    from stale s
   where l.id = s.id;

  get diagnostics v_count = row_count;

  -- No explicit audit writes above. The revocation is an ordinary UPDATE, so
  -- the trigger in 0400 produces the sla_revoked entries. One audit code path
  -- for humans and machines means the two can never drift apart.

  perform set_config('app.actor_kind', 'user', true);
  perform set_config('app.audit_note', '', true);

  return v_count;
end $$;

comment on function public.recycle_stale_leads() is
  'Returns the number of leads reclaimed. Safe to call concurrently. Returns 0 '
  'immediately when stale_recycling_enabled is false.';


-- ---------------------------------------------------------------------------
-- admin_run_recycle_now — manual sweep from the Settings panel
-- ---------------------------------------------------------------------------
-- Lets an admin verify the configuration without waiting up to 15 minutes for
-- the next tick.
create or replace function public.admin_run_recycle_now()
returns integer
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  return public.recycle_stale_leads();
end $$;


-- ---------------------------------------------------------------------------
-- Execution grants
-- ---------------------------------------------------------------------------
-- The engine itself is unreachable from the API surface; admins get to it only
-- through the wrapper above, which enforces the role check.
revoke execute on function public.recycle_stale_leads()   from public, anon, authenticated;
revoke execute on function public.admin_run_recycle_now() from public;
grant  execute on function public.admin_run_recycle_now() to authenticated;


-- ---------------------------------------------------------------------------
-- Schedule
-- ---------------------------------------------------------------------------
-- Every 15 minutes. An SLA measured in hours does not need second-level
-- precision, and leads_sla_sweep_idx (a narrow partial index on assigned_at
-- where status = 'new') makes each sweep cheap enough to be uninteresting.
--
-- The ON/OFF toggle is checked *inside* the function, so switching the feature
-- off in the admin UI is instant and the job itself is never rescheduled.
do $outer$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice
      'pg_cron is not installed — the stale-lead sweep is NOT scheduled. '
      'Enable it (Dashboard > Database > Extensions) and re-run this migration, '
      'or call public.admin_run_recycle_now() from an external scheduler.';
    return;
  end if;

  -- cron.schedule() would silently create a second job on re-run.
  if exists (select 1 from cron.job where jobname = 'recycle-stale-leads') then
    perform cron.unschedule('recycle-stale-leads');
  end if;

  perform cron.schedule(
    'recycle-stale-leads',
    '*/15 * * * *',
    $cron$select public.recycle_stale_leads();$cron$
  );

  raise notice 'Scheduled "recycle-stale-leads" every 15 minutes.';
end $outer$;

-- END 20260814000800_recycling_engine.sql


-- ============================================================================
-- BEGIN 20260814000900_seed.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 0900 — Configuration Seed & Admin Bootstrap
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Singleton settings row. Idempotent: safe to replay.
-- ---------------------------------------------------------------------------
insert into public.system_settings (
  id,
  stale_recycling_enabled,
  stale_sla_hours,
  whatsapp_template,
  round_robin_cursor,
  report_timezone
)
values (
  true,
  true,
  72,
  'Hello {{name}}, this is {{agent}} from Fenlark Technologies. '
  'Thank you for your interest in our digital marketing and web development '
  'services. When would be a good time to connect?',
  0,
  'Asia/Kolkata'
)
on conflict (id) do nothing;


-- ---------------------------------------------------------------------------
-- bootstrap_first_admin — resolves the chicken-and-egg problem
-- ---------------------------------------------------------------------------
-- admin_set_user_role() requires an existing admin to call it, and
-- enforce_user_update_rules() blocks self-promotion. So the very first admin
-- cannot be created through the API at all — by design.
--
-- This function is the one-time escape hatch. It refuses to run once any
-- active admin exists, and EXECUTE is revoked from every API-reachable role,
-- so it is usable only from the Supabase SQL editor or a direct psql session.
--
-- Usage: sign the person up through the app first, then run
--     select public.bootstrap_first_admin('you@fenlark.in');
create or replace function public.bootstrap_first_admin(p_email text)
returns public.users
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row public.users;
begin
  if exists (select 1 from public.users where role = 'admin' and is_active) then
    raise exception 'an active admin already exists'
      using hint = 'Use admin_set_user_role() from an admin session instead.';
  end if;

  -- enforce_user_update_rules() would otherwise reject the role change, since
  -- there is no admin in existence to authorise it.
  perform set_config('app.actor_kind', 'system', true);

  update public.users
     set role = 'admin'
   where lower(email) = lower(btrim(p_email))
  returning * into v_row;

  perform set_config('app.actor_kind', 'user', true);

  if v_row.id is null then
    raise exception 'no user found with email %', p_email
      using hint = 'Sign the user up through the app first, then re-run this.';
  end if;

  return v_row;
end $$;

revoke execute on function public.bootstrap_first_admin(text)
  from public, anon, authenticated;

-- END 20260814000900_seed.sql


-- ============================================================================
-- BEGIN 20260814001000_security_hardening.sql
-- ============================================================================

-- ============================================================================
-- Fenlark CRM · 1000 — Security Hardening
-- ============================================================================
-- Findings from the security audit. The headline fix is C-1: an authenticated
-- telecaller could bypass log_call_interaction's validation entirely with a
-- direct PostgREST table write on their own leads — confirmed exploitable
-- against the live project, not theoretical.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- C-1 — Revoke direct write access to public.leads
-- ---------------------------------------------------------------------------
-- RLS correctly answered "is this row yours?", but that was the wrong question
-- on its own: owning the row let a telecaller UPDATE status / scheduled_at /
-- last_remark directly, skipping the remark requirement and the future-date
-- check that log_call_interaction enforces. Observed consequences:
--   * mark leads 'converted' with no remark (audit trail records the change
--     but loses the reason)
--   * push scheduled_at into 2099 to zero out their own overdue counter
--     without logging a single call
--   * write status='rescheduled' with a null follow-up date
--
-- Every legitimate write already goes through a SECURITY DEFINER RPC, which
-- executes as the table owner and is unaffected by these grants. Removing
-- client write access therefore breaks nothing and makes the RPC the only
-- door in. SELECT is deliberately untouched — telecallers must still read
-- their own queue.
revoke insert, update, delete on public.leads from authenticated, anon;

-- The row policies stay in place as a second layer, in case a grant is ever
-- restored by a future migration or by Supabase default privileges.


-- ---------------------------------------------------------------------------
-- C-2 — Revoke EXECUTE from anon explicitly
-- ---------------------------------------------------------------------------
-- Supabase's default privileges grant EXECUTE to anon/authenticated *by name*
-- when a function is created, so the `REVOKE ... FROM PUBLIC` in migration
-- 0500 never actually removed it — anon could still reach is_admin() and
-- admin_run_recycle_now(). Neither was exploitable (each rejects unauthorised
-- callers internally), but the grant layer should agree with the intent
-- rather than leaving the internal check as the only thing standing.
revoke execute on function public.is_admin()                                    from anon;
revoke execute on function public.owns_lead(uuid)                               from anon;
revoke execute on function public.normalize_phone(text)                         from anon;
revoke execute on function public.my_dashboard_stats()                          from anon;
revoke execute on function public.log_call_interaction(uuid, public.lead_status, text, timestamptz) from anon;
revoke execute on function public.admin_import_leads(jsonb, public.lead_source)  from anon;
revoke execute on function public.admin_assign_leads(uuid[], uuid)              from anon;
revoke execute on function public.admin_round_robin_assign(uuid[], uuid[])      from anon;
revoke execute on function public.admin_archive_lead(uuid, text)                from anon;
revoke execute on function public.admin_update_settings(boolean, integer, text) from anon;
revoke execute on function public.admin_set_user_role(uuid, public.user_role)   from anon;
revoke execute on function public.admin_set_user_active(uuid, boolean)          from anon;
revoke execute on function public.admin_run_recycle_now()                       from anon;


-- ---------------------------------------------------------------------------
-- Harden the system-actor escape hatch
-- ---------------------------------------------------------------------------
-- is_system_actor() trusts a GUC. PostgREST gives clients no way to set an
-- arbitrary GUC, so this was not reachable — but pinning it to a non-API role
-- means the flag can only ever be trusted inside our own SECURITY DEFINER
-- functions, whatever connection path exists in future.
--
-- Tested against role *names* rather than a hardcoded owner ('postgres'):
-- this keeps working if the schema owner ever differs, and it states the
-- actual intent — a client-facing connection can never claim to be the system.
create or replace function public.is_system_actor()
returns boolean
language sql
stable
as $$
  select coalesce(nullif(current_setting('app.actor_kind', true), ''), 'user') = 'system'
     and current_user not in ('anon', 'authenticated');
$$;


-- ---------------------------------------------------------------------------
-- C-3 — Replace `USING (true)` on system_settings
-- ---------------------------------------------------------------------------
-- Telecallers need exactly two fields; they were getting the whole config row
-- including round_robin_cursor and updated_by (an admin's UUID).
--
-- security_invoker = false so this runs with the view owner's rights and stays
-- readable once the underlying table becomes admin-only.
create or replace view public.app_settings
with (security_invoker = false) as
  select whatsapp_template, report_timezone
  from public.system_settings
  where id = true;

revoke all on public.app_settings from anon, authenticated;
grant select on public.app_settings to authenticated;

comment on view public.app_settings is
  'Non-sensitive slice of system_settings for telecallers. The full row is '
  'admin-only via settings_select_admin.';

-- REGRESSION GUARD: public.lead_queue is security_invoker = true and reads
-- stale_sla_hours in a subquery to compute sla_hours_remaining. Locking the
-- table to admins would silently return NULL there for every telecaller and
-- kill the "returns to pool in Nh" warning in the disposition drawer — a
-- failure with no error to notice. This accessor keeps that one value
-- reachable without reopening the whole row.
create or replace function public.sla_hours()
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select stale_sla_hours from public.system_settings where id = true;
$$;

revoke execute on function public.sla_hours() from public, anon;
grant  execute on function public.sla_hours() to authenticated;

create or replace view public.lead_queue
with (security_invoker = true) as
select
  l.*,
  case
    when l.status in ('converted', 'dead')            then 'closed'
    when l.scheduled_at is null                       then 'unscheduled'
    when l.scheduled_at <  now()                      then 'overdue'
    when l.scheduled_at <  now() + interval '2 hours' then 'due_soon'
    when l.scheduled_at <  now() + interval '24 hours' then 'due_today'
    else 'scheduled'
  end as follow_up_bucket,
  case
    when l.status in ('converted', 'dead')            then 90
    when l.scheduled_at <  now()                      then 10
    when l.scheduled_at <  now() + interval '2 hours' then 20
    when l.scheduled_at <  now() + interval '24 hours' then 30
    when l.status = 'new'                             then 40
    when l.scheduled_at is not null                   then 50
    else 60
  end as queue_rank,
  case
    when l.status = 'new' and l.assigned_at is not null then
      greatest(
        0,
        public.sla_hours()
        - (extract(epoch from (now() - l.assigned_at)) / 3600)
      )
    else null
  end as sla_hours_remaining
from public.leads l
where l.deleted_at is null;

revoke all on public.lead_queue from anon, authenticated;
grant select on public.lead_queue to authenticated;

-- Now safe to lock the table itself down.
drop policy if exists settings_select on public.system_settings;
drop policy if exists settings_select_admin on public.system_settings;
create policy settings_select_admin on public.system_settings
  for select to authenticated
  using (public.is_admin());


-- ---------------------------------------------------------------------------
-- L-5 — Aggregate dashboard counts inside Postgres
-- ---------------------------------------------------------------------------
-- The admin dashboard was pulling every lead row to count them in JavaScript.
-- PostgREST caps responses at 1000 rows by default, so at lead #1001 the
-- pipeline donut and the reclaimed-leads total would have started reporting
-- quietly wrong numbers with no error anywhere.
create or replace function public.admin_dashboard_summary()
returns table (
  total_leads       integer,
  unassigned        integer,
  active_callers    integer,
  sla_revoked_total integer,
  status_counts     jsonb
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  return query
  select
    (select count(*) from public.leads where deleted_at is null)::integer,
    (select count(*) from public.leads where deleted_at is null and assigned_to is null)::integer,
    (select count(*) from public.users where role = 'telecaller' and is_active)::integer,
    (select coalesce(sum(sla_revoked_count), 0) from public.leads where deleted_at is null)::integer,
    (select coalesce(jsonb_object_agg(s.status, s.n), '{}'::jsonb)
       from (
         select status, count(*) as n
         from public.leads
         where deleted_at is null
         group by status
       ) s);
end $$;

revoke execute on function public.admin_dashboard_summary() from public, anon;
grant  execute on function public.admin_dashboard_summary() to authenticated;

-- END 20260814001000_security_hardening.sql


-- ============================================================================
-- BEGIN 20260816001100_call_sessions.sql
-- ============================================================================

-- ============================================================================
-- Trace · 1100 — Call Sessions (live call tracking)
-- ============================================================================
-- Records when a telecaller starts a call and how long it lasted, so the admin
-- dashboard can show who is on a call right now and how much talk time each
-- caller logged.
--
-- WHY A SEPARATE TABLE, not lead_history_logs: a call session is *mutable* —
-- it is created when the call starts and updated when it ends. The audit trail
-- is append-only and its prevent_log_mutation() trigger raises on any UPDATE,
-- so a session row physically cannot live there. The audit trail keeps
-- recording dispositions; this table records call activity.
--
-- ACCURACY, stated plainly: the app cannot observe the native dialer. There is
-- no browser API for call state (the W3C Telephony spec was never implemented).
-- The client measures how long the app was backgrounded while the dialer was in
-- front, which includes ringing time, so durations run slightly long and are
-- confirmable by the telecaller before saving. `duration_source` records where
-- a number came from, so if calls are ever routed through a cloud telephony
-- provider its exact webhook values can be written into this same table
-- alongside the estimates, without a schema change.


-- ---------------------------------------------------------------------------
-- Table
-- ---------------------------------------------------------------------------
create table if not exists public.call_sessions (
  id            uuid primary key default gen_random_uuid(),

  lead_id       uuid not null references public.leads (id),
  -- Matches lead_history_logs.actor_id: a departed telecaller's account can be
  -- deleted without erasing the fact that the call happened.
  caller_id     uuid references public.users (id) on delete set null,

  started_at    timestamptz not null default now(),
  ended_at      timestamptz,

  -- Null while in progress, and deliberately left null for swept sessions —
  -- an abandoned session's duration is unknown, and writing a fabricated one
  -- would quietly corrupt talk-time reporting.
  duration_seconds integer check (duration_seconds is null or duration_seconds >= 0),

  duration_source  text not null default 'app_estimate'
                     check (duration_source in ('app_estimate', 'manual', 'provider')),

  -- How the session was closed. 'sweep' means the app never reported back
  -- (browser closed mid-call, phone died), so the row is closed for hygiene
  -- but excluded from duration statistics.
  ended_reason  text check (ended_reason in ('user', 'superseded', 'sweep')),

  created_at    timestamptz not null default now()
);

-- The live panel's query: every session still in progress.
create index if not exists call_sessions_active_idx
  on public.call_sessions (started_at desc)
  where ended_at is null;

-- Per-caller reporting and the "today" rollups.
create index if not exists call_sessions_caller_idx
  on public.call_sessions (caller_id, started_at desc);

create index if not exists call_sessions_lead_idx
  on public.call_sessions (lead_id, started_at desc);

-- A caller can only be on one call at a time. start_call_session() already
-- closes any previous open session, so this is a backstop against a race
-- between two devices rather than something the UI should ever hit.
create unique index if not exists call_sessions_one_active_per_caller
  on public.call_sessions (caller_id)
  where ended_at is null;

comment on table public.call_sessions is
  'Call activity per telecaller. Durations are app-measured estimates unless '
  'duration_source = ''provider''. Rows with ended_reason = ''sweep'' have a '
  'null duration and must be excluded from talk-time totals.';


-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
alter table public.call_sessions enable row level security;

grant select on public.call_sessions to authenticated;
-- No INSERT/UPDATE/DELETE grant, on purpose. This is the C-1 lesson from
-- migration 1000: owning a row is not permission to write it however you like.
-- The SECURITY DEFINER RPCs below are the only write path, so the ownership
-- and duration rules cannot be bypassed by a direct PostgREST call.
revoke insert, update, delete on public.call_sessions from authenticated, anon;

drop policy if exists call_sessions_select on public.call_sessions;
create policy call_sessions_select on public.call_sessions
  for select to authenticated
  using (public.is_admin() or caller_id = auth.uid());


-- ---------------------------------------------------------------------------
-- start_call_session
-- ---------------------------------------------------------------------------
create or replace function public.start_call_session(p_lead_id uuid)
returns public.call_sessions
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor   uuid := auth.uid();
  v_lead    public.leads;
  v_session public.call_sessions;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select * into v_lead
  from public.leads
  where id = p_lead_id and deleted_at is null;

  if not found then
    raise exception 'lead not found' using errcode = 'P0002';
  end if;

  -- Same ownership rule as log_call_interaction. SECURITY DEFINER bypasses
  -- RLS, so this check is the only thing standing in for it.
  if not (public.is_admin() or v_lead.assigned_to = v_actor) then
    raise exception 'forbidden: this lead is not assigned to you'
      using errcode = '42501';
  end if;

  -- Close any session this caller left open — tapping Call on a second lead
  -- without dispositioning the first is normal behaviour, not an error, so it
  -- resolves silently instead of blocking the new call on the unique index.
  update public.call_sessions
     set ended_at     = now(),
         ended_reason = 'superseded'
   where caller_id = v_actor and ended_at is null;

  insert into public.call_sessions (lead_id, caller_id)
  values (p_lead_id, v_actor)
  returning * into v_session;

  return v_session;
end $$;


-- ---------------------------------------------------------------------------
-- end_call_session
-- ---------------------------------------------------------------------------
-- p_duration_seconds is what the client measured (time the app spent
-- backgrounded, or a value the telecaller corrected by hand). When omitted the
-- wall-clock elapsed time is used instead.
--
-- Idempotent: the client can fire this from both a visibilitychange handler
-- and an explicit "End call" tap, and a page reload can retry it. Ending an
-- already-ended session returns the existing row rather than raising, so those
-- races cannot surface as an error to a telecaller mid-call.
create or replace function public.end_call_session(
  p_session_id       uuid,
  p_duration_seconds integer default null,
  p_source           text    default 'app_estimate'
)
returns public.call_sessions
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor    uuid := auth.uid();
  v_session  public.call_sessions;
  v_duration integer;
begin
  if v_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_source not in ('app_estimate', 'manual', 'provider') then
    raise exception 'invalid duration source: %', p_source;
  end if;

  select * into v_session
  from public.call_sessions
  where id = p_session_id
  for update;

  if not found then
    raise exception 'call session not found' using errcode = 'P0002';
  end if;

  if not (public.is_admin() or v_session.caller_id = v_actor) then
    raise exception 'forbidden: this call session is not yours'
      using errcode = '42501';
  end if;

  -- Already closed. Two different situations:
  --   * the auto path firing twice (visibilitychange + an explicit tap, or a
  --     retry after a reload) — must be a no-op, never an overwrite
  --   * an explicit correction, where the telecaller edited the duration in
  --     the disposition form before saving — p_source = 'manual' is the signal
  --
  -- Worth being clear about the trust model: in this design the duration is
  -- always client-reported, so a telecaller can influence their own talk-time
  -- figure whether or not this correction path exists. Treat it as a work
  -- record, not an audited metric. Routing calls through a telephony provider
  -- (duration_source = 'provider') is what would make it tamper-proof.
  if v_session.ended_at is not null then
    if p_source = 'manual' and p_duration_seconds is not null then
      update public.call_sessions
         set duration_seconds = least(greatest(p_duration_seconds, 0), 4 * 60 * 60),
             duration_source  = 'manual'
       where id = p_session_id
      returning * into v_session;
    end if;
    return v_session;
  end if;

  v_duration := coalesce(
    p_duration_seconds,
    greatest(0, extract(epoch from (now() - v_session.started_at))::integer)
  );

  -- A sanity ceiling. A "14 hour call" is always the app having been
  -- backgrounded overnight, and letting it through would wreck the averages.
  if v_duration > 4 * 60 * 60 then
    v_duration := null;
  end if;

  update public.call_sessions
     set ended_at         = now(),
         duration_seconds = v_duration,
         duration_source  = p_source,
         ended_reason     = 'user'
   where id = p_session_id
  returning * into v_session;

  return v_session;
end $$;


-- ---------------------------------------------------------------------------
-- sweep_abandoned_calls — pg_cron housekeeping
-- ---------------------------------------------------------------------------
-- Sessions the app never closed (browser killed mid-call, phone died) would
-- otherwise sit "in progress" forever and show as a permanent live call on the
-- admin dashboard. Duration is left null: it is genuinely unknown.
create or replace function public.sweep_abandoned_calls(p_max_minutes integer default 120)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.call_sessions
     set ended_at     = now(),
         ended_reason = 'sweep'
   where ended_at is null
     and started_at < now() - make_interval(mins => p_max_minutes);

  get diagnostics v_count = row_count;
  return v_count;
end $$;

do $$
begin
  perform cron.unschedule('sweep-abandoned-calls');
exception when others then
  null; -- not scheduled yet
end $$;

do $$
begin
  perform cron.schedule(
    'sweep-abandoned-calls',
    '*/5 * * * *',
    $cron$select public.sweep_abandoned_calls();$cron$
  );
exception when others then
  raise notice 'pg_cron unavailable; sweep-abandoned-calls not scheduled';
end $$;


-- ---------------------------------------------------------------------------
-- Admin reporting RPCs
-- ---------------------------------------------------------------------------
-- Who is on a call right now. Joined server-side so the dashboard gets names
-- in one round trip rather than resolving ids client-side.
create or replace function public.admin_active_calls()
returns table (
  session_id  uuid,
  caller_id   uuid,
  caller_name text,
  lead_id     uuid,
  lead_name   text,
  lead_phone  text,
  started_at  timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  return query
  select cs.id, cs.caller_id, u.full_name, cs.lead_id, l.full_name, l.phone, cs.started_at
  from public.call_sessions cs
  left join public.users u on u.id = cs.caller_id
  join public.leads l on l.id = cs.lead_id
  where cs.ended_at is null
  order by cs.started_at asc;
end $$;

-- Per-caller totals for the current day, in the configured report timezone —
-- same reasoning as my_dashboard_stats: a UTC day boundary would reset the
-- counter at 05:30 IST, mid-shift.
create or replace function public.admin_call_stats_today()
returns table (
  caller_id     uuid,
  caller_name   text,
  calls_today   integer,
  talk_seconds  integer,
  longest_call  integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_tz    text;
  v_start timestamptz;
begin
  if not public.is_admin() then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  select report_timezone into v_tz from public.system_settings where id = true;
  v_tz := coalesce(v_tz, 'Asia/Kolkata');
  v_start := date_trunc('day', now() at time zone v_tz) at time zone v_tz;

  return query
  select
    u.id,
    u.full_name,
    count(cs.id)::integer,
    -- Swept sessions carry a null duration and are excluded by coalesce/sum
    -- rather than counted as zero-length calls.
    coalesce(sum(cs.duration_seconds), 0)::integer,
    coalesce(max(cs.duration_seconds), 0)::integer
  from public.users u
  join public.call_sessions cs
    on cs.caller_id = u.id and cs.started_at >= v_start
  group by u.id, u.full_name
  order by coalesce(sum(cs.duration_seconds), 0) desc;
end $$;


-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
revoke execute on function public.start_call_session(uuid)                     from public, anon;
revoke execute on function public.end_call_session(uuid, integer, text)        from public, anon;
revoke execute on function public.sweep_abandoned_calls(integer)              from public, anon, authenticated;
revoke execute on function public.admin_active_calls()                         from public, anon;
revoke execute on function public.admin_call_stats_today()                     from public, anon;

grant execute on function public.start_call_session(uuid)               to authenticated;
grant execute on function public.end_call_session(uuid, integer, text)  to authenticated;
grant execute on function public.admin_active_calls()                   to authenticated;
grant execute on function public.admin_call_stats_today()               to authenticated;


-- ---------------------------------------------------------------------------
-- Realtime
-- ---------------------------------------------------------------------------
-- Lets the admin dashboard subscribe to call activity instead of polling.
-- Delivery still respects the RLS policy above, so a telecaller subscribing to
-- this table would only ever receive their own rows.
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'call_sessions'
  ) then
    alter publication supabase_realtime add table public.call_sessions;
  end if;
exception when undefined_object then
  raise notice 'supabase_realtime publication not present; skipping';
end $$;

-- END 20260816001100_call_sessions.sql


-- ============================================================================
-- BEGIN 20260816001200_fix_audit_fk_nulling.sql
-- ============================================================================

-- ============================================================================
-- Trace · 1200 — Let user deletion null the audit trail's person references
-- ============================================================================
-- BUG THIS FIXES: deleting a telecaller failed with "Database error deleting
-- user" for any account that had ever been assigned a lead — i.e. every real
-- telecaller. The admin Telecallers screen's Delete button simply did not work.
--
-- The mechanism: lead_history_logs.actor_id / from_assignee / to_assignee are
-- all `on delete set null`, precisely so a departed telecaller's account can be
-- removed without erasing the fact that something happened. But nulling them is
-- an UPDATE on lead_history_logs, and prevent_log_mutation() rejected *every*
-- UPDATE unconditionally. So the FK action and the immutability guard were in
-- direct conflict, and the guard won — taking the delete down with it.
--
-- The fix keeps the trail immutable where it matters. An UPDATE is permitted
-- only when every column describing *what happened* is byte-identical and the
-- sole change is a person reference going from set to null. Anything else —
-- editing a remark, changing a status, re-pointing a log at a different user,
-- or restoring a nulled reference — still raises, and DELETE/TRUNCATE remain
-- blocked outright.
--
-- Note this is the inner of two defences: `authenticated` has no UPDATE grant
-- on lead_history_logs at all, so no client can reach this path regardless.
-- The only caller is the FK action itself, running as the table owner.

create or replace function public.prevent_log_mutation()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'UPDATE' then
    if  new.id           is not distinct from old.id
    and new.lead_id      is not distinct from old.lead_id
    and new.actor_kind   is not distinct from old.actor_kind
    and new.event_type   is not distinct from old.event_type
    and new.from_status  is not distinct from old.from_status
    and new.to_status    is not distinct from old.to_status
    and new.remark       is not distinct from old.remark
    and new.scheduled_at is not distinct from old.scheduled_at
    and new.note         is not distinct from old.note
    and new.created_at   is not distinct from old.created_at
    -- Each person reference may either stay exactly as it was, or become null.
    -- It may never change to a *different* user, and a nulled one may never be
    -- repopulated — that would let history be re-attributed after the fact.
    and (new.actor_id      is not distinct from old.actor_id      or new.actor_id      is null)
    and (new.from_assignee is not distinct from old.from_assignee or new.from_assignee is null)
    and (new.to_assignee   is not distinct from old.to_assignee   or new.to_assignee   is null)
    then
      return new;
    end if;
  end if;

  raise exception
    'lead_history_logs is append-only; % is not permitted on the audit trail', tg_op
    using errcode = '42501',
          hint = 'Corrections are made by adding a new log entry, never by editing one.';
end $$;

comment on function public.prevent_log_mutation() is
  'Append-only guard. The single exception is a user deletion nulling '
  'actor_id/from_assignee/to_assignee via their on-delete-set-null foreign '
  'keys; the narrative of every entry stays immutable.';


-- ---------------------------------------------------------------------------
-- Second half of the same bug
-- ---------------------------------------------------------------------------
-- With the guard above relaxed, deleting a telecaller got one step further and
-- then failed differently: the delete nulls leads.assigned_to (also
-- on delete set null), which fires log_lead_change, which tries to INSERT an
-- 'unassigned' entry carrying from_assignee = the user currently being
-- deleted. Their public.users row is already gone by that point in the cascade,
-- so the new row's own foreign key fails.
--
-- Fix: resolve assignee references through an existence check before writing
-- them. A vanished user is recorded as null, which is exactly what the
-- on-delete-set-null design says a departed telecaller looks like — the event
-- is still recorded, it just no longer points at a row that does not exist.
create or replace function public.log_lead_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_kind  text := coalesce(nullif(current_setting('app.actor_kind', true), ''), 'user');
  v_note  text := nullif(current_setting('app.audit_note', true), '');
  v_from  uuid;
  v_to    uuid;
begin
  -- A system action is attributed to the system, never to whoever happened to
  -- be logged in. admin_run_recycle_now() runs under an admin's JWT, so without
  -- this the same SLA revocation would read "Aditi revoked this lead" when
  -- triggered from the settings panel and "system" when triggered by cron —
  -- for a decision neither of them made. The SLA did.
  if v_kind = 'system' then
    v_actor := null;
  end if;

  -- The actor can vanish mid-cascade for the same reason an assignee can.
  if v_actor is not null
     and not exists (select 1 from public.users where id = v_actor) then
    v_actor := null;
  end if;

  if tg_op = 'INSERT' then
    select new.assigned_to into v_to
    where exists (select 1 from public.users where id = new.assigned_to);

    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, to_status, to_assignee, note
    )
    values (new.id, v_actor, v_kind, 'lead_created', new.status, v_to, v_note);

    -- A lead created already-assigned produces two entries, so the assignment
    -- has its own timestamped record rather than being implied by creation.
    if new.assigned_to is not null then
      insert into public.lead_history_logs (
        lead_id, actor_id, actor_kind, event_type, to_assignee
      )
      values (new.id, v_actor, v_kind, 'assigned', v_to);
    end if;

    return null;
  end if;

  -- ---- UPDATE ----

  if new.assigned_to is distinct from old.assigned_to then
    v_from := null;
    v_to   := null;
    select old.assigned_to into v_from
      where exists (select 1 from public.users where id = old.assigned_to);
    select new.assigned_to into v_to
      where exists (select 1 from public.users where id = new.assigned_to);

    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, from_assignee, to_assignee, note
    )
    values (
      new.id, v_actor, v_kind,
      case
        when old.assigned_to is null                     then 'assigned'
        when new.assigned_to is null and v_kind = 'system' then 'sla_revoked'
        when new.assigned_to is null                     then 'unassigned'
        else 'reassigned'
      end::public.audit_event,
      v_from, v_to, v_note
    );
  end if;

  if new.status is distinct from old.status then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, from_status, to_status, note
    )
    values (new.id, v_actor, v_kind, 'status_changed', old.status, new.status, v_note);
  end if;

  -- Only forward-looking reschedules are logged; clearing the date on a
  -- converted/dead lead is bookkeeping, not a follow-up commitment.
  if new.scheduled_at is distinct from old.scheduled_at
     and new.scheduled_at is not null then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, scheduled_at
    )
    values (new.id, v_actor, v_kind, 'reschedule_set', new.scheduled_at);
  end if;

  if new.deleted_at is not null and old.deleted_at is null then
    insert into public.lead_history_logs (
      lead_id, actor_id, actor_kind, event_type, note
    )
    values (new.id, v_actor, v_kind, 'lead_archived', v_note);
  end if;

  -- NOTE: changes to last_remark are deliberately not logged here.
  -- public.log_call_interaction() writes the authoritative 'remark_added'
  -- entry with its own before/after status; logging it here as well would
  -- double every remark on the timeline.

  return null;
end $$;

-- END 20260816001200_fix_audit_fk_nulling.sql

